// 一、地点结构（每个地点长这样）
//   {
//     id:        'cafe',        ← 英文ID，整个文件不能重复
//     name:      '咖啡厅',      ← 显示名称
//     icon:      '☕',          ← Emoji图标
//     desc:      '地点简介...',  ← 在选择界面里显示的一句话
//     moneyBase: 150,            ← 薪酬参考值（仅用于界面显示）
//     events: [                  ← 该地点下的随机剧情列表
//       { ...事件A... },
//       { ...事件B... },
//     ]
//   }
//
// 二、事件结构（每个事件长这样）
//
//   {
//     id:    'cafe_evt1',       ← 事件ID，整个文件不能重复
//     title: '事件标题',        ← 显示在弹窗顶部
//     story: [                  ← 铺垫文字，每5段自动翻页
//       '第一段描述。',
//       '第二段描述。',
//       '第三段描述，引入冲突。',
//     ],
//     choices: [                ← 选项列表（见下方四种写法）
//       { ...选项1... },
//       { ...选项2... },
//     ]
//   }
//
// 三、选项的四种写法
// 【写法A：固定结果（最简单）】
// 选了就是这个结果，不随机，不看性别。
//   {
//     text:   '选项按钮上的文字',
//     result: '选择后显示的剧情。\n\n空一行用两个\\n。',
//     money:  200,              // 正=获得金钱，负=损失金钱，0=不变
//     expChanges: {             // 经验变化（可以整段删掉不写）
//       '调教经验': 2,
//       '口交经验': 1,
//     }
//   }
//
// 【写法B：随机结果（掷骰子）】
// 选了之后，50%走A结果，50%走B结果。概率可以自己调整。
//   {
//     text: '选项按钮上的文字',
//     dynamicOutcome: () => {
//       const roll = Math.random(); // 生成 0~1 之间的随机数
//       if (roll < 0.5) {
//         // ← 把 0.5 改成 0.3 就是 30% 概率，改成 0.7 就是 70%
//         return {
//           result: '好结果的剧情文字。',
//           money: 500,
//           expChanges: { '调教经验': 1 }
//         };
//       } else {
//         return {
//           result: '坏结果的剧情文字。',
//           money: 0,
//         };
//       }
//     }
//   }
//
// 【写法C：性别分支】
// 男性玩家和女性玩家看到不同剧情。
//
//   {
//     text: '选项按钮上的文字',
//     dynamicOutcome: () => {
//       const gender = _workGetGender(); // 返回 '男' 或 '女'
//       if (gender === '女') {
//         return {
//           result: '女性玩家专属剧情。',
//           money: 0,
//         };
//       }
//       // 默认（男性玩家）
//       return {
//         result: '男性玩家剧情。',
//         money: 100,
//       };
//     }
//   }
//
// ─────────────────────────────────────────────────────────────
// 【写法D：性别 + 随机 双重判断（最复杂，但很灵活）】
//
//   {
//     text: '选项按钮上的文字',
//     dynamicOutcome: () => {
//       const gender = _workGetGender();
//       const roll = Math.random();
//       if (gender === '女') {
//         if (roll < 0.5) return { result: '女性·好结局', money: 200 };
//         return { result: '女性·坏结局', money: 0 };
//       }
//       if (roll < 0.5) return { result: '男性·好结局', money: 200 };
//       return { result: '男性·坏结局', money: 0 };
//     }
//   }
//
// ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
// 四、经验名称速查（填 expChanges 时用）
//
//   '调教经验'     '口交经验'     '性交经验'     '内射经验'
//   '肛射经验'     '射精经验'     '绝顶经验'     '自慰经验'
//   '痛苦快乐经验' '嗜虐快乐经验' '爱情经验'     '精液经验'
//   '支配经验'     '紧缚经验'     '家务经验'     '歌唱经验'
//   'Ａ经验'       'V经验'
//
// 五、快速添加新地点（三步走）
//
//   第一步：复制下面任意一个模板地点 { id: ... }
//   第二步：修改 id / name / icon / desc / moneyBase 和事件内容
//   第三步：粘贴到 WORK_LOCATIONS 数组的末尾（在最后一个 }, 后面）
//

// ── 辅助函数：获取玩家性别 ──────────────────────────────────
// 所有"写法C/D"的 dynamicOutcome 都调用这个函数。
// 如果游戏存储方式有变化，只需要改这一个地方即可。
function _workGetGender() {
  if (typeof _playerProfile !== 'undefined' && _playerProfile && _playerProfile.gender) return _playerProfile.gender;
  if (window.State && State.playerGender) return State.playerGender;
  if (window.State && State.masterGender) return State.masterGender;
  try { var p = JSON.parse(localStorage.getItem('era_profile') || '{}'); if (p.gender) return p.gender; } catch(e){}
  return '男';
}


